/**
 * Trình quản lý kho tri thức theo nhãn (Tag Knowledge Manager)
 */
class TagKnowledgeManager {
    constructor() {
        // Lưu trữ kho tri thức (ánh xạ từ Nhãn -> Mục tri thức)
        this.tagToEntry = new Map();

        // Danh mục nhãn (tất cả các nhãn khả dụng)
        this.catalog = [];

        // Trạng thái đã tải hay chưa
        this.loaded = false;

        console.log('[Kho tri thức nhãn] Khởi tạo trình quản lý');
    }

    /**
     * Tải kho tri thức (sử dụng dữ liệu được nhúng sẵn)
     */
    async load() {
        console.log('[Kho tri thức nhãn] Bắt đầu tải kho tri thức nhúng sẵn...');

        try {
            // Tải danh mục
            this.catalog = EMBEDDED_KNOWLEDGE_DATA.catalog.allTags || [];
            console.log(`[Kho tri thức nhãn] Tải danh mục thành công, tổng cộng có ${this.catalog.length} nhãn`);

            // Tải tri thức về tư thế (position)
            const positions = EMBEDDED_KNOWLEDGE_DATA.positions || [];
            for (const entry of positions) {
                if (entry.tags && Array.isArray(entry.tags)) {
                    for (const tag of entry.tags) {
                        this.tagToEntry.set(tag.toLowerCase(), entry);
                        this.tagToEntry.set(tag, entry);
                    }
                }
                if (entry.title) {
                    this.tagToEntry.set(entry.title.toLowerCase(), entry);
                    this.tagToEntry.set(entry.title, entry);
                }
            }
            console.log(`[Kho tri thức nhãn] Kho tri thức tư thế: Đã tải ${positions.length} mục`);

            this.loaded = true;
            console.log(`[Kho tri thức nhãn] ✅ Tải hoàn tất, tổng cộng có ${this.tagToEntry.size} ánh xạ nhãn`);

            return true;
        } catch (error) {
            console.error('[Kho tri thức nhãn] Tải thất bại:', error);
            return false;
        }
    }

    /**
     * Lấy danh mục nhãn (dùng cho API phân tích)
     */
    getCatalog() {
        return this.catalog;
    }

    /**
     * Lấy văn bản danh mục nhãn đã định dạng
     */
    getCatalogText() {
        if (this.catalog.length === 0) {
            return '';
        }
        return `Các nhãn tri thức khả dụng: ${this.catalog.join('、')}`;
    }

    /**
     * Truy xuất nội dung tri thức dựa trên nhãn
     */
    retrieveByTags(tags) {
        if (!tags) return [];

        const tagList = Array.isArray(tags) ? tags : [tags];
        const results = [];
        const seen = new Set();

        for (const tag of tagList) {
            if (!tag) continue;

            let entry = this.tagToEntry.get(tag);
            if (!entry) {
                entry = this.tagToEntry.get(tag.toLowerCase());
            }

            if (entry && !seen.has(entry.id)) {
                seen.add(entry.id);
                results.push(entry);
            }
        }

        console.log(`[Kho tri thức nhãn] Truy xuất nhãn [${tagList.join(', ')}] -> Tìm thấy ${results.length} mục`);
        return results;
    }

    /**
     * Xây dựng ngữ cảnh tri thức (dùng để chèn vào API chính)
     */
    buildKnowledgeContext(entries) {
        if (!entries || entries.length === 0) {
            return '';
        }

        let context = '【📚 Tham khảo tri thức liên quan】\n';
        context += 'Dưới đây là tham khảo miêu tả tri thức liên quan đến phân cảnh hiện tại, vui lòng vận dụng linh hoạt theo tình huống thực tế:\n\n';

        entries.forEach((entry, index) => {
            context += `${index + 1}. ${entry.content}\n\n`;
        });

        return context;
    }

    /**
     * Kiểm tra xem đã tải hay chưa
     */
    isLoaded() {
        return this.loaded;
    }

    /**
     * Tải lại (Reload)
     */
    async reload() {
        this.tagToEntry.clear();
        this.catalog = [];
        this.loaded = false;
        return await this.load();
    }
}

// Tạo thực thể (instance) toàn cục
window.tagKnowledgeManager = new TagKnowledgeManager();

// Tải ngay lập tức (không cần trì hoãn vì đây là dữ liệu nhúng sẵn)
window.tagKnowledgeManager.load();

console.log('[Kho tri thức nhãn] Module đã được tải');
